import React from "react";
import { FaLinkedin, FaGithub, FaEnvelope } from "react-icons/fa";

const Footer = () => {
  return (
    <>
      <style>{`

        .footer {
          background: #0b1120;
          color: #cbd5e1;
          padding: 22px 8%;
          border-top: 1px solid rgba(255,255,255,0.06);
        }

        .footer-container {
          display: flex;
          flex-direction: column;
          align-items: center;
          gap: 14px;
          text-align: center;
        }

        /* LOGO + NAME */
        .footer-top {
          display: flex;
          align-items: center;
          gap: 10px;
        }

        .footer-logo {
          width: 34px;
          height: 34px;
          border-radius: 8px;
          display: flex;
          align-items: center;
          justify-content: center;
          font-weight: 600;
          font-size: 14px;
          color: white;
          background: linear-gradient(135deg, #38BDF8, #2563eb);
          box-shadow: 0 0 10px rgba(56,189,248,0.4);
        }

        .footer-name {
          font-size: 15px;
          font-weight: 500;
          color: #e2e8f0;
        }

        /* TAGLINE */
        .footer-text {
          font-size: 14px;
          color: #94a3b8;
        }

        /* CTA BUTTON */
        .footer-cta {
          margin-top: 4px;
        }

        .footer-cta a {
          text-decoration: none;
          padding: 8px 18px;
          border-radius: 20px;
          font-size: 13px;
          color: white;
          background: linear-gradient(135deg, #38BDF8, #2563eb);
          transition: 0.3s;
          display: inline-block;
        }

        .footer-cta a:hover {
          transform: translateY(-2px);
          box-shadow: 0 0 12px rgba(56,189,248,0.5);
        }

        /* ICONS */
        .footer-icons {
          display: flex;
          gap: 12px;
          margin-top: 6px;
        }

        .footer-icons a {
          width: 30px;
          height: 30px;
          display: flex;
          align-items: center;
          justify-content: center;
          border-radius: 50%;
          background: rgba(255,255,255,0.05);
          color: #cbd5e1;
          font-size: 13px;
          transition: 0.25s;
        }

        .footer-icons a:hover {
          background: #38BDF8;
          color: white;
          transform: translateY(-2px);
        }

        /* COPYRIGHT */
        .footer-copy {
          font-size: 11px;
          color: #64748b;
          margin-top: 6px;
        }

      `}</style>

      <footer className="footer">
        <div className="footer-container">

          {/* TOP */}
          <div className="footer-top">
            <div className="footer-logo">SA</div>
            <div className="footer-name">Swetha</div>
          </div>

          {/* TAGLINE */}
          <div className="footer-text">
            Let’s build something impactful together.
          </div>

          {/* CTA BUTTON */}
          <div className="footer-cta">
            <a href="/contact">Contact Me →</a>
          </div>

          {/* ICONS */}
          <div className="footer-icons">
            <a href="mailto:swethaa1805@email.com">
              <FaEnvelope />
            </a>

            <a
              href="https://www.linkedin.com/in/swetha-a-0b1712382/"
              target="_blank"
              rel="noopener noreferrer"
            >
              <FaLinkedin />
            </a>

            <a
              href="https://github.com/Swethaa1805"
              target="_blank"
              rel="noopener noreferrer"
            >
              <FaGithub />
            </a>
          </div>

          {/* COPYRIGHT */}
          <div className="footer-copy">
            © {new Date().getFullYear()} Swetha
          </div>

        </div>
      </footer>
    </>
  );
};

export default Footer;
